// Package postgres is the history's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/history"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform"
)

// Repo implements history.Repo.
type Repo struct {
	q *Queries
}

var _ history.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Append stores e and returns its id.
func (r *Repo) Append(ctx context.Context, e platform.Event) (int64, error) {
	return r.q.InsertEvent(ctx, InsertEventParams{UserID: e.UserID, Kind: e.Kind, Subject: e.Subject,
		Data: e.Data, At: e.At})
}

// After returns user's events with an id above after, oldest first.
func (r *Repo) After(ctx context.Context, user, after int64, limit int) ([]platform.Event, error) {
	rows, err := r.q.EventsAfter(ctx, EventsAfterParams{UserID: user, ID: after, Limit: int32(min(limit, 1<<20))}) //nolint:gosec // capped
	if err != nil {
		return nil, err
	}
	out := make([]platform.Event, len(rows))
	for i, row := range rows {
		out[i] = platform.Event{ID: row.ID, UserID: row.UserID, Kind: row.Kind, Subject: row.Subject,
			Data: row.Data, At: row.At}
	}
	return out, nil
}
